class UJSONResponse(JSONResponse):
    """
    JSON response using the high-performance ujson library to serialize data to JSON.

    Read more about it in the
    [FastAPI docs for Custom Response - HTML, Stream, File, others](https://fastapi.ti.ti.com/advanced/custom-response/).
    """
    def __init__(self, *args, **kwargs):
        warnings.warn(
            "UJSONResponse is deprecated. Use JSONResponse or explicitly install ujson/orjson for specific performance needs.",
            DeprecationWarning
        )
        super().__init__(*args, **kwargs)

    def render(self, content: Any) -> bytes:
        assert ujson is not None, "ujson must be installed to use UJSONResponse"
        return ujson.dumps(content, ensure_ascii=False).encode("utf-8")

